DO $$ DECLARE old_row public.admin_wallet_operations%ROWTYPE; paid_row public.admin_wallet_operations%ROWTYPE; BEGIN SELECT * INTO old_row FROM public.admin_wallet_operations WHERE id='29d61751-9d99-4699-a989-66632d3a1203' FOR UPDATE; SELECT * INTO paid_row FROM public.admin_wallet_operations WHERE id='706e7047-ff2f-4e06-b94b-9f48b72ab6bf' FOR UPDATE; IF old_row.status <> 'pending' OR paid_row.status <> 'completed' OR old_row.amount <> 10000 OR paid_row.amount <> 10000 OR old_row.target_user_id <> paid_row.target_user_id OR old_row.destination_phone <> paid_row.destination_phone OR old_row.operation_type <> 'withdraw' OR paid_row.operation_type <> 'withdraw' OR paid_row.gateway_reference IS NULL THEN RAISE EXCEPTION 'Request state changed; cancellation stopped'; END IF; IF EXISTS (SELECT 1 FROM public.ledger_entries WHERE metadata->>'admin_wallet_operation_id'=old_row.id::text) OR old_row.gateway_reference IS NOT NULL OR old_row.ledger_reference IS NOT NULL THEN RAISE EXCEPTION 'Pending request has financial activity; cancellation stopped'; END IF; UPDATE public.admin_wallet_operations SET status='cancelled',execution_error='Duplicate request cancelled: the replacement UGX 10,000 withdrawal was already paid.',metadata=COALESCE(metadata,'{}'::jsonb)||jsonb_build_object('superseded_by_operation_id',paid_row.id,'cancellation_reason','Unpaid failed attempt superseded by completed payment','cancelled_at',now()) WHERE id=old_row.id AND status='pending'; INSERT INTO public.audit_logs(action,table_name,record_id,record_data,reason,performed_by) VALUES ('cancel_unpaid_duplicate_withdrawal','admin_wallet_operations',old_row.id::text,jsonb_build_object('before',to_jsonb(old_row),'completed_operation_id',paid_row.id,'payment_reference',paid_row.gateway_reference,'money_changed',false),'Fauza Kelvis reported already-paid Benson UGX 10,000 withdrawal still pending; failed original request had no ledger or gateway activity.','kelvisfauza@gmail.com'); END $$;